<?php
    $transaction_details = pp_get_transation($payment_id);
    $setting = pp_get_settings();
    $plugin_slug = 'bangla-qr-manual';
    $plugin_info = pp_get_plugin_info($plugin_slug);
    $settings = pp_get_plugin_setting($plugin_slug);
    $base_amount = convertToDefault($transaction_details['response'][0]['transaction_amount'], $transaction_details['response'][0]['transaction_currency'], $settings['currency']);
    $transaction_fee = safeNumber($settings['fixed_charge']) + ($base_amount * (safeNumber($settings['percent_charge']) / 100));
    $transaction_amount = $base_amount + $transaction_fee;

    if(isset($_POST['bangla-qr-manual-slip'])){
        if(pp_set_transaction_byslip($payment_id, $plugin_slug, $plugin_info['plugin_name'], $_FILES['payment_slip'] ?? null, 'pending')){
            echo json_encode(["status" => "true", "message" => "Receipt uploaded"]);
        }else{
            echo json_encode(["status" => "false", "message" => "Failed to upload receipt"]);
        }
        exit();
    }
    if(isset($_POST['bangla-qr-manual'])){
        $number = trim((string) ($_POST['number'] ?? ''));
        if($number === '' || strlen($number) > 100 || !preg_match('/^[A-Za-z0-9+\s_-]+$/', $number)){
            echo json_encode(["status" => "false", "message" => "Enter your MFS number or bank account number"]);
        }else{
            if(($settings['pending_payment'] ?? 'enable') == "enable"){
                if(pp_set_transaction_byid($payment_id, $plugin_slug, $plugin_info['plugin_name'], $number, $number, 'pending')) echo json_encode(["status" => "true", "message" => "Payment submitted for review"]);
                else echo json_encode(["status" => "false", "message" => "Unable to submit payment. Please try again."]);
            }else echo json_encode(["status" => "false", "message" => "Manual payments are currently disabled"]);
        }
        exit();
    }
    $payment_number = $settings['payment_number'] ?? '';
    $display_payment_number = preg_match('/^(\d{3})(\d{4})(\d{4})$/', preg_replace('/\D/', '', (string) $payment_number), $number_parts) ? $number_parts[1].' '.$number_parts[2].' '.$number_parts[3] : $payment_number;
    $currency_symbols = ['BDT' => '৳', 'USD' => '$', 'EUR' => '€', 'GBP' => '£', 'INR' => '₹', 'PKR' => '₨', 'AED' => 'د.إ', 'SAR' => '﷼', 'CAD' => 'C$', 'AUD' => 'A$', 'JPY' => '¥', 'CNY' => '¥'];
    $currency_symbol = $currency_symbols[strtoupper($settings['currency'] ?? '')] ?? ($settings['currency'] ?? '');
    $amount = number_format($transaction_amount, 2).' '.$currency_symbol;
    $logo = pp_get_site_url().'/pp-content/plugins/'.$plugin_info['plugin_dir'].'/'.$plugin_slug.'/assets/icon.png';
    $has_qr = !empty($settings['qr_code']);
    $qr_src = $has_qr ? $settings['qr_code'] : 'https://api.qrserver.com/v1/create-qr-code/?size=240x240&data='.urlencode('BanglaQR '.$payment_number.' '.$amount);
?>
