recipient strong{font-size:16px}.verified{color:#2F80ED;font-size:16px}.recipient strong,.recipient .verified{margin-top:0}.recipient-name{display:flex;align-items:center;justify-content:center;gap:6px}.account-name{color:#fff;background:#006A4E;border-radius:10px;padding:5px}.account-type{font-size:12px;color:var(--muted);margin-top:5px;margin-bottom:-2px}.recipient strong{display:inline-block}.recipient .verified{margin-left:0}.phone{position:relative;display:inline-flex;align-items:center;justify-content:center;min-width:188px;width:100%;background:transparent;border:0;border-top:0;border-bottom:0;border-radius:0;padding:12px 14px;font-size:16px;font-weight:600}.phone-number{white-space:nowrap}.phone-number strong{font-size:18px;font-weight:700}.phone>i{font-size:16px}.copy{position:static;border:0;background:none;color:var(--pink);cursor:pointer;font:600 12px Inter;padding:0;margin-left:8px}.scan{text-align:center}.scan h2{font-size:14px;color:var(--muted);font-weight:400;margin:0 0 8px}.qr-frame{position:relative;width:220px;height:220px;margin:auto;padding:6px}.qr-frame:before{content:'';position:absolute;z-index:2;inset:0;pointer-events:none;background:linear-gradient(var(--pink),var(--pink)) top left/18px 3px no-repeat,linear-gradient(var(--pink),var(--pink)) top left/3px 18px no-repeat,linear-gradient(var(--pink),var(--pink)) top right/18px 3px no-repeat,linear-gradient(var(--pink),var(--pink)) top right/3px 18px no-repeat,linear-gradient(var(--pink),var(--pink)) bottom left/18px 3px no-repeat,linear-gradient(var(--pink),var(--pink)) bottom left/3px 18px no-repeat,linear-gradient(var(--pink),var(--pink)) bottom right/18px 3px no-repeat,linear-gradient(var(--pink),var(--pink)) bottom right/3px 18px no-repeat;border-radius:0}.qr{position:relative;z-index:1;display:block;width:208px;height:208px;padding:6px;margin:auto;border:0;border-radius:0;box-shadow:none;background:#fff}.qr-dl{position:absolute;z-index:3;right:-14px;bottom:-14px;width:40px;height:40px;display:grid;place-items:center;border:1px solid var(--line);border-radius:50%;background:#fff;color:var(--pink);box-shadow:0 6px 16px rgba(26,26,26,.14);cursor:pointer;transition:.2s}.qr-dl:hover{background:var(--pink);border-color:var(--pink);color:#fff;transform:translateY(-1px)}.qr-dl i{font-size:16px}.form-area{border-top:1px solid var(--line);margin-top:30px;padding-top:26px}.verify-tabs{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:4px;border:1px solid var(--line);border-radius:14px;background:#F8F9FB;margin-bottom:20px}.verify-tab{border:0;border-radius:10px;background:transparent;color:var(--muted);font:700 13px Inter,sans-serif;padding:11px 8px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;transition:.2s}.verify-tab.active{background:#fff;color:var(--pink);box-shadow:0 2px 8px rgba(26,26,26,.08)}.verify-pane{display:none}.verify-pane.active{display:block}.upload-box{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:10px 14px;min-height:96px;padding:14px 16px;border:1.5px dashed #9CC5B8;border-radius:16px;background:#FBFDFC;text-align:left;transition:border-color .2s,background .2s;cursor:pointer}.upload-box:hover,.upload-box.has-file{border-color:var(--pink);background:#EFF8F3}.upload-copy{display:flex;align-items:center;min-width:0;gap:10px}.upload-icon{display:grid;flex:0 0 auto;width:34px;height:34px;place-items:center;border-radius:10px;background:#DFF0E7;color:var(--pink)}.upload-icon i{font-size:16px}.upload-title{margin:0;color:#263958;font-size:13px;font-weight:700;white-space:nowrap}.choose-file{display:inline-flex;align-items:center;justify-content:center;align-self:center;padding:9px 14px;border:1px solid #9CC5B8;border-radius:9px;background:#fff;color:var(--pink);font-size:12px;font-weight:700;white-space:nowrap}.file-helper{grid-column:1;grid-row:2;align-self:center;margin:0 0 0 44px;color:#9aa7ba;font-size:10px}.file-name{grid-column:1 / -1;max-width:100%;margin:0;overflow:hidden;color:#118935;font-size:12px;font-weight:700;text-overflow:ellipsis;white-space:nowrap}.slip-input{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}.field{margin-bottom:18px}.field label{display:block;margin-bottom:8px;color:var(--ink)}.input-wrap{position:relative}.input-wrap i{position:absolute;left:17px;top:50%;transform:translateY(-50%);color:#A2A6AD;font-size:15px;line-height:1;z-index:1}.input{width:100%;height:54px;border:1px solid var(--line);border-radius:15px;padding:0 18px 0 46px;line-height:54px;font:inherit;outline:0;background:#FCFCFD}.input:focus{border-color:var(--pink);box-shadow:0 0 0 4px rgba(0,106,78,.12)}.btn-pay{width:100%;height:auto;padding:15px 20px;border:0;border-radius:16px;background:linear-gradient(100deg,var(--pink),#00805E);color:#fff;font:700 14px Inter;cursor:pointer;box-shadow:0 10px 20px rgba(0,106,78,.22);transition:.2s}.btn-pay:hover{filter:brightness(1.08);box-shadow:0 12px 26px rgba(0,106,78,.3)}.response{display:block;margin-bottom:12px}.alert{padding:12px;border-radius:12px;font-size:13px;background:#fff0f0;color:#c0392b}.footer{text-align:center;color:#9a9da3;font-size:12px;margin-top:22px}@media(max-width:600px){.page{width:calc(100% - 20px);margin-top:18px}.main{padding:22px}.pay-grid{grid-template-columns:1fr;gap:25px}.divider{height:1px;width:100%}.divider span{padding:7px 10px}.scan{padding-top:3px}.price{font-size:32px}.amount{padding:24px}.top{margin-bottom:16px}}
