<body><main class="page"><header class="top" style="padding:18px 20px 0"><button class="back" onclick="location.href='<?php echo pp_get_paymentlink($payment_id)?>'" aria-label="Back"><i class="fa-solid fa-arrow-left"></i><span>Back</span></button><img src="<?php echo $logo?>" alt="Bangla QR"><span aria-hidden="true"></span></header>
<section class="card amount"><div class="eyebrow">Amount to Pay</div><div class="price"><?php echo $amount?></div></section>
<section class="card main"><div class="pay-grid"><div class="scan"><h2>Scan to Pay</h2><div class="qr-frame"><img class="qr" id="bqr-qr-img" src="<?php echo htmlspecialchars($qr_src); ?>" alt="Payment QR code"><button type="button" class="qr-dl" id="bqr-qr-dl" aria-label="Download QR code" title="Download QR"><i class="fa-solid fa-download"></i></button></div></div></div>
<div class="form-area"><div class="verify-tabs" role="tablist" aria-label="Verification method"><button type="button" class="verify-tab active" data-pane="number-pane" role="tab" aria-selected="true"><i class="fa-solid fa-qrcode"></i>Account Number</button><button type="button" class="verify-tab" data-pane="slip-pane" role="tab" aria-selected="false"><i class="fa-solid fa-cloud-arrow-up"></i>Upload Receipt</button></div><div class="verify-pane active" id="number-pane"><div class="field"><label for="bqr-number">MFS (bKash, Nagad, etc.) Number / Bank Account Number</label><div class="input-wrap"><i class="fa-solid fa-building-columns"></i><input class="input sender-number" id="bqr-number" name="bqr-number" placeholder="Number or account you paid from"></div></div><span class="response" aria-live="polite"></span><button class="btn-pay" type="button"><i class="fa-solid fa-shield-halved"></i>&nbsp; Verify</button></div><div class="verify-pane" id="slip-pane"><div class="field"><label class="upload-label" id="bqr-slip-label" style="display:block;margin-bottom:8px;color:var(--ink)">Upload payment receipt</label><label class="upload-box" for="bqr-slip"><span class="upload-copy"><span class="upload-icon"><i class="fa-solid fa-cloud-arrow-up"></i></span><span class="upload-title">Drop your receipt here</span></span><span class="choose-file">Choose File</span><span class="file-helper">JPG • PNG • PDF • Max 5MB</span><span class="file-name" aria-live="polite"></span></label><input id="bqr-slip" name="payment-slip" class="slip-input" type="file" accept="image/jpeg,image/png,application/pdf" aria-labelledby="bqr-slip-label"></div><span class="response-slip" aria-live="polite"></span><button class="btn-pay btn-slip" type="button"><i class="fa-solid fa-cloud-arrow-up"></i>&nbsp; Upload Receipt</button></div></div></section><footer class="footer">Secure payment verification · Powered by <strong>KeyClan</strong></footer></main>
<script>
function copyText(text,button){if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(text).then(function(){var original=button.innerHTML;button.innerHTML='<i class="fa-solid fa-check"></i>';button.disabled=true;setTimeout(function(){button.innerHTML=original;button.disabled=false},2000)})}}
document.getElementById('bqr-qr-dl')?.addEventListener('click',async function(){var img=document.getElementById('bqr-qr-img');if(!img||!img.src)return;var btn=this;try{var res=await fetch(img.src,{mode:'cors'});var blob=await res.blob();var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='bangla-qr-payment.png';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},4000)}catch(e){var f=document.createElement('a');f.href=img.src;f.download='bangla-qr-payment.png';f.target='_blank';f.rel='noopener';document.body.appendChild(f);f.click();f.remove()}});
$('.verify-tab').on('click',function(){var pane=$(this).data('pane');$('.verify-tab').removeClass('active').attr('aria-selected','false');$(this).addClass('active').attr('aria-selected','true');$('.verify-pane').removeClass('active');$('#'+pane).addClass('active')});
var slipInput=document.getElementById('bqr-slip');var slipBox=document.querySelector('#slip-pane .upload-box');var slipName=document.querySelector('#slip-pane .file-name');slipInput?.addEventListener('change',function(){var f=this.files[0];if(!f)return;slipBox?.classList.add('has-file');if(slipName)slipName.textContent=f.name});
$('.btn-slip').on('click',function(){var btn=this,file=slipInput?.files[0];var box=$('#slip-pane .response-slip');box.text('').removeClass('alert');if(!file){box.text('Please choose your payment receipt first.').addClass('alert');return}if(file.size>5*1024*1024){box.text('Your receipt must be smaller than 5MB.').addClass('alert');return}btn.disabled=true;var orig=btn.innerHTML;btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i>&nbsp; Uploading…';var fd=new FormData();fd.append('bangla-qr-manual-slip','<?php echo $payment_id?>');fd.append('payment_slip',file);$.ajax({type:'POST',url:'<?php echo pp_get_paymentlink($payment_id)?>?method=bangla-qr-manual',data:fd,contentType:false,processData:false,success:function(data){try{var r=JSON.parse(data);if(r.status==='true'){location.href='<?php echo pp_get_paymentlink($payment_id)?>'}else{box.text(r.message||'Upload failed.').addClass('alert');btn.disabled=false;btn.innerHTML=orig}}catch(e){box.text('Unable to process the receipt. Please try again.').addClass('alert');btn.disabled=false;btn.innerHTML=orig}},error:function(){box.text('Unable to upload the receipt. Please try again.').addClass('alert');btn.disabled=false;btn.innerHTML=orig}})});
$('.btn-pay').not('.btn-slip').on('click',function(){var btn=this,number=$('.sender-number').val();if(!number){$('.response').text('Enter your MFS number or bank account number').addClass('alert');return}btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i>';$.ajax({type:'POST',url:'<?php echo pp_get_paymentlink($payment_id)?>?method=bangla-qr-manual',data:{'bangla-qr-manual':'<?php echo $payment_id?>',number:number},success:function(data){btn.innerHTML='<i class="fa-solid fa-shield-halved"></i>&nbsp; Verify';var result=JSON.parse(data);if(result.status==='false'){$('.response').text(result.message || 'Request failed').addClass('alert')}else location.href='<?php echo pp_get_paymentlink($payment_id)?>'}})})
</script></body></html>
